const binSize=5;function key(x,z){return `${Math.floor(x/binSize)},${Math.floor(z/binSize)}`}function buildSpatialIndex(data){grid.clear();for(let i=0;i<data.runs.length;i++)for(let j=0;j<data.runs[i].segments.length;j++){const s=data.runs[i].segments[j],p=s.corners,xs=p.map(q=>q[0]),zs=p.map(q=>q[2]);for(let x=Math.floor((Math.min(...xs)-.35)/binSize);x<=Math.floor((Math.max(...xs)+.35)/binSize);x++)for(let z=Math.floor((Math.min(...zs)-.35)/binSize);z<=Math.floor((Math.max(...zs)+.35)/binSize);z++){const k=`${x},${z}`;if(!grid.has(k))grid.set(k,[]);grid.get(k).push(s)}}}
