function makeRobot(pos){const g=new THREE.Group(),body= new THREE.Mesh(new THREE.BoxGeometry(.72,.30,.82),material(0x287ec0,.5));body.position.y=.37;g.add(body);const dome=new THREE.Mesh(new THREE.SphereGeometry(.23,16,10),material(0xdbefff,.35));dome.position.set(0,.66,-.04);g.add(dome);const mast=new THREE.Mesh(new THREE.CylinderGeometry(.035,.035,.24,8),material(0xf3bd47,.5));mast.position.set(0,.89,0);g.add(mast);for(const x of [-.39,.39])for(const z of [-.26,.26]){const w=new THREE.Mesh(new THREE.CylinderGeometry(.12,.12,.10,12),material(0x29353c,.8));w.rotation.z=Math.PI/2;w.position.set(x,.16,z);g.add(w)}scene.add(g);robot=g;robotPos={x:pos[0],y:pos[1],z:pos[2]};robot.position.set(pos[0],pos[1],pos[2]);}
function canOccupy(x,z){const h=footprintSupport(x,z);return h.ok?h:{ok:false,reason:h.reason||'no_nav_surface'}}function moveTo(x,z){const x0=robotPos.x,z0=robotPos.z,dx=x-x0,dz=z-z0,d=Math.hypot(dx,dz),n=Math.max(1,Math.ceil(d/.08));for(let i=1;i<=n;i++){const px=x0+dx*i/n,pz=z0+dz*i/n,q=canOccupy(px,pz);if(!q.ok){moveStats.blocked++;return false}robotPos={x:px,y:q.y,z:pz};robot.position.set(px,q.y,pz);moveStats.ok++;if(q.review)moveStats.review++}return true}
function safetyProbes(){const find=reason=>{for(const r of navData.runs)for(const s of r.segments)if(s.reason===reason){const p=s.corners;return canOccupy(p.reduce((a,v)=>a+v[0],0)/4,p.reduce((a,v)=>a+v[2],0)/4)}return {ok:true}};const gap=gapAreas[0],b=phaseData.bounds;return {stairs:!find('stairs_are_not_auto-climbable_for_wheeled_proxy').ok,steepSlope:!find('grade_over_35_percent').ok,omittedGap:!canOccupy(gap.centerXY[0],gap.centerXY[1]).ok,boundary:!canOccupy(b[2]+2,(b[1]+b[3])/2).ok}}
function runAutoTest(){if(!testRoute||testRoute.points.length<2){result.textContent='連続した移動可能ルートがありません';return}const pts=testRoute.points;let travelled=0,probes=0,failed=null,review=0;const start=[...pts[0]];robotPos={x:start[0],y:start[1],z:start[2]};robot.position.set(...start);for(let k=1;k<pts.length&&!failed;k++){const a=pts[k-1],b=pts[k],d=Math.hypot(b[0]-a[0],b[2]-a[2]),steps=Math.max(1,Math.ceil(d/.08));for(let i=1;i<=steps;i++){const f=i/steps,x=a[0]+(b[0]-a[0])*f,z=a[2]+(b[2]-a[2])*f,h=canOccupy(x,z);probes++;if(!h.ok){failed={x,z,reason:h.reason};break}if(h.review)review++;robotPos={x,y:h.y,z};travelled+=d/steps}}robot.position.set(robotPos.x,robotPos.y,robotPos.z);robot.rotation.y=Math.atan2(-(pts.at(-1)[0]-pts[0][0]),-(pts.at(-1)[2]-pts[0][2]));const checks=safetyProbes(),checkText=`stairs ${checks.stairs?'BLOCK':'FAIL'} · >35% ${checks.steepSlope?'BLOCK':'FAIL'} · gap ${checks.omittedGap?'BLOCK':'FAIL'} · boundary ${checks.boundary?'BLOCK':'FAIL'}`;result.textContent=failed?`停止: ${travelled.toFixed(1)}m / ${failed.reason} @ ${failed.x.toFixed(1)}, ${failed.z.toFixed(1)} · ${checkText}`:`PASS · ${travelled.toFixed(1)}m · ${probes} swept probes · 要確認通過 ${review} · ${checkText}`;status.textContent=`自動移動テスト ${failed?'停止':'完了'} · way ${testRoute.wayId} · ${testRoute.lengthMetres}m`}
let driveMode='drive',driveCamera='chase',driveCourse=null,bus=null,driveHeading=0,driveSteer=0,driveSpeed=0,driveCoursePhase='outbound',driveBlocked=0,driveDistanceAlong=0,driveDebugGroup=new THREE.Group(),driveLineGroup=new THREE.Group(),driveWire=null,driveObstacles=[],driveLastReason='',driveWheelbase=2.4,driveMaxSteer=16*Math.PI/180;
scene.add(driveDebugGroup,driveLineGroup);
const DRIVE_HALF_WIDTH=1.36,DRIVE_HALF_LENGTH=2.26,DRIVE_MARGIN=.12,DRIVE_MAX_GRADE=.12,DRIVE_MAX_SPEED=3.2,DRIVE_MAX_REVERSE=1.35;
function drivePointAt(s){const p=driveCourse.points;let station=0;for(let i=1;i<p.length;i++){const a=p[i-1],b=p[i],dx=b[0]-a[0],dz=b[2]-a[2],len=Math.hypot(dx,dz);if(s<=station+len){const t=len?(s-station)/len:0;return{x:a[0]+dx*t,y:a[1]+(b[1]-a[1])*t,z:a[2]+dz*t,heading:Math.atan2(dx,dz),grade:len?(b[1]-a[1])/len:0,station:s}}station+=len}const a=p[p.length-2],b=p[p.length-1];return{x:b[0],y:b[1],z:b[2],heading:Math.atan2(b[0]-a[0],b[2]-a[2]),grade:0,station}}
function driveProject(x,z){const p=driveCourse.points;let best={dist:Infinity,station:0,y:0,grade:0,heading:0};let station=0;for(let i=1;i<p.length;i++){const a=p[i-1],b=p[i],dx=b[0]-a[0],dz=b[2]-a[2],len=Math.hypot(dx,dz),l2=len*len,t=l2?Math.max(0,Math.min(1,((x-a[0])*dx+(z-a[2])*dz)/l2)):0,px=a[0]+t*dx,pz=a[2]+t*dz,d=Math.hypot(x-px,z-pz);if(d<best.dist)best={dist:d,station:station+t*len,y:a[1]+t*(b[1]-a[1]),grade:len?(b[1]-a[1])/len:0,heading:Math.atan2(dx,dz)};station+=len}return best}
function driveObstacleHits(x,z,h){const fx=Math.sin(h),fz=Math.cos(h),rx=Math.cos(h),rz=-Math.sin(h),corners=[];for(const l of [-DRIVE_HALF_LENGTH,DRIVE_HALF_LENGTH])for(const w of [-DRIVE_HALF_WIDTH,DRIVE_HALF_WIDTH])corners.push([x+fx*l+rx*w,z+fz*l+rz*w]);for(const t of driveObstacles){if(t.polygon){const inside=p=>{let hit=false;for(let i=0,j=t.polygon.length-1;i<t.polygon.length;j=i++){const a=t.polygon[i],b=t.polygon[j];if(((a[1]>p[1])!==(b[1]>p[1]))&&(p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0]))hit=!hit}return hit};if(corners.some(inside)||inside([x,z]))return true;continue}const dx=t.x-x,dz=t.z-z,long=dx*fx+dz*fz,lat=dx*rx+dz*rz;if(Math.abs(long)<DRIVE_HALF_LENGTH+t.r&&Math.abs(lat)<DRIVE_HALF_WIDTH+t.r)return true}return false}
function driveFootprintCheck(x,z,h){const f={x:Math.sin(h),z:Math.cos(h)},r={x:Math.cos(h),z:-Math.sin(h)};for(const longitudinal of [-DRIVE_HALF_LENGTH,0,DRIVE_HALF_LENGTH])for(const lateral of [-DRIVE_HALF_WIDTH,0,DRIVE_HALF_WIDTH]){const px=x+f.x*longitudinal+r.x*lateral,pz=z+f.z*longitudinal+r.z*lateral,q=driveProject(px,pz);if(q.station<-.08||q.station>driveCourse.lengthMetres+.08)return{ok:false,reason:'コース端外 · BLOCK'};const half=Math.min(driveCourse.widthMetres/2,q.widthMetres/2||driveCourse.widthMetres/2);if(q.dist>half-DRIVE_MARGIN)return{ok:false,reason:'車体が園路境界へ接近 · BLOCK'};if(Math.abs(q.grade)>DRIVE_MAX_GRADE)return{ok:false,reason:'勾配上限超過 · BLOCK'}}if(driveObstacleHits(x,z,h))return{ok:false,reason:'樹木・植え込みへ接近 · 安全停止'};return{ok:true,reason:'OK'}}
function makeDriveLines(){const p=driveCourse.points.map(q=>new THREE.Vector3(q[0],q[1]+.13,q[2])),line=new THREE.Line(new THREE.BufferGeometry().setFromPoints(p),new THREE.LineDashedMaterial({color:0xffd34f,dashSize:1.5,gapSize:.55,depthTest:false}));line.computeLineDistances();line.name='Course A · estimated drive centerline';line.userData={notMeasured:driveCourse.widthBasis};driveLineGroup.add(line);let d=0;for(let i=1;i<driveCourse.points.length;i++){const a=driveCourse.points[i-1],b=driveCourse.points[i],dx=b[0]-a[0],dz=b[2]-a[2],len=Math.hypot(dx,dz);if(!len)continue;const nx=-dz/len, nz=dx/len,hw=driveCourse.widthMetres/2;for(const sign of [-1,1]){const edge=new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(a[0]+nx*hw,a[1]+.17,a[2]+nz*hw),new THREE.Vector3(b[0]+nx*hw,b[1]+.17,b[2]+nz*hw)]),new THREE.LineBasicMaterial({color:sign<0?0x52a7ff:0xff7d56,transparent:true,opacity:.55,depthTest:false}));driveLineGroup.add(edge)}d+=len;if(Math.floor(d/8)!==Math.floor((d-len)/8)){const s=Math.min(d,driveCourse.lengthMetres),q=drivePointAt(s),ring=new THREE.Mesh(new THREE.TorusGeometry(1.2,.075,6,24),new THREE.MeshBasicMaterial({color:0xffed85,depthTest:false}));ring.rotation.x=Math.PI/2;ring.position.set(q.x,q.y+.25,q.z);ring.userData.station=s;driveLineGroup.add(ring)}}driveLineGroup.visible=true}
function makeDriveDebug(){driveDebugGroup.clear();driveWire=new THREE.LineSegments(new THREE.EdgesGeometry(new THREE.BoxGeometry(driveCourse.busDimensionsMetres.widthIncludingMirrors+DRIVE_MARGIN*2,driveCourse.busDimensionsMetres.height+DRIVE_MARGIN,driveCourse.busDimensionsMetres.length+DRIVE_MARGIN*2)),new THREE.LineBasicMaterial({color:0xff4e72,depthTest:false}));driveWire.name='Bus safety envelope (estimated)';driveWire.position.y=driveCourse.busDimensionsMetres.height/2;driveWire.visible=false;bus.add(driveWire)}
function driveHud(message){const s=$('#driveStatus');if(s)s.textContent=message;status.textContent=message;$('#speedDisplay').textContent=(Math.abs(driveSpeed)*3.6).toFixed(1)+' km/h'+(driveSpeed<-.02?' · R':'');$('#checkpointDisplay').textContent=driveCoursePhase==='outbound'?'OUT · '+Math.max(0,driveCourse.lengthMetres-2.8-driveDistanceAlong).toFixed(1)+'m':'RETURN · '+Math.max(0,driveDistanceAlong-2.8).toFixed(1)+'m';}
function setDriveMode(mode){driveMode=mode;const driving=mode==='drive';driveGroup.visible=driving;gameGroup.visible=!driving;game.active=!driving&&!game.clear&&!game.over;game.paused=driving;$('#modeDrive').classList.toggle('active',driving);$('#modeBattle').classList.toggle('active',!driving);$('#vehicleHud').style.display=driving?'grid':'none';$('#health').style.display=driving?'none':'grid';$('#gameStatus').style.display=driving?'none':'block';$('#testResult').style.display='block';if(driving){viewMode='bus';driveCamera='chase';}else{setView('robot')}driveHud(driving?'DRIVE MODE · Aコース限定 · 推定幅4.0m / 要現地確認':'BATTLE MODE · Phase 3A · Phase 2C navigation unchanged')}
function resetDrive(){if(!bus||!driveCourse)return;driveSpeed=0;driveSteer=0;driveCoursePhase='outbound';const p=drivePointAt(2.8);driveDistanceAlong=2.8;bus.position.set(p.x,p.y+.02,p.z);driveHeading=p.heading;bus.rotation.set(-Math.atan(p.grade),driveHeading,0);driveBlocked=0;driveLastReason='';driveHud('Aコース · 発進できます · 前方チェックポイントへ');setDriveMode('drive')}
function driveCollisionTrees(veg){const all=[...(veg.mappedTrees||[]),...(veg.estimatedTrees||[])];driveObstacles=all.map(t=>({x:t.x,z:t.z,r:.24}));for(const s of (veg.estimatedShrubs||[]))driveObstacles.push({x:s.x,z:s.z,r:.42});}
function makeStaticObstacles(data){for(const f of [...(data.features.water||[]),...(data.features.buildings||[])]){const poly=(f.points||[]).map(p=>[p[0],p[2]]);if(poly.length>=3)driveObstacles.push({polygon:poly})}}
async function initDrive(){const response=await fetch('../../data/processed/phaseD1/drive_courses.json');if(!response.ok)throw new Error('D1 course JSON HTTP '+response.status);driveCourse=(await response.json()).courses.A;driveWheelbase=driveCourse.busDimensionsMetres.wheelbase;driveMaxSteer=16*Math.PI/180;const loadedBus=await loadTayoBus('./tayo_bus_phaseD1.glb');bus=loadedBus;bus.name='Tayo bus · read-only exported GLB';driveGroup.add(bus);driveCollisionTrees(vegetationData||{});makeStaticObstacles(phaseData);makeDriveLines();makeDriveDebug();$('#courseSelect').addEventListener('change',e=>{if(e.target.value!=='A'){e.target.value='A';driveHud('B/Cは車体掃引未検証 · BLOCK')}else resetDrive()});$('#driveDebug').addEventListener('change',e=>{if(driveWire)driveWire.visible=e.target.checked});$('#modeDrive').addEventListener('click',()=>setDriveMode('drive'));$('#modeBattle').addEventListener('click',()=>setDriveMode('battle'));$('#cameraToggle').addEventListener('click',()=>{driveCamera=driveCamera==='chase'?'above':'chase'});$('#viewRobot').textContent='追従カメラ';$('#viewRobot').addEventListener('click',()=>{if(driveMode==='drive')driveCamera='chase';else setView('robot')});$('#viewAbove').addEventListener('click',()=>{driveMode==='drive'?driveCamera='above':setView('top')});$('#test').addEventListener('click',()=>{setDriveMode('battle');runAutoTest()});$('#restart').addEventListener('click',()=>driveMode==='drive'?resetDrive():restartGame());driveHud('Tayoバス GLB読込完了 · Aコース限定');resetDrive();}
function updateDrive(dt){if(!bus||driveMode!=='drive')return;const acc=keys.has('w')?2.0:0,brake=keys.has('s');if(acc)driveSpeed=Math.min(DRIVE_MAX_SPEED,driveSpeed+acc*dt);else if(brake){if(driveSpeed>.18)driveSpeed=Math.max(0,driveSpeed-4.2*dt);else driveSpeed=Math.max(-DRIVE_MAX_REVERSE,driveSpeed-1.25*dt)}else driveSpeed*=Math.max(0,1-.72*dt);const steerInput=(keys.has('d')?1:0)-(keys.has('a')?1:0);driveSteer=steerInput*driveMaxSteer;if(Math.abs(driveSpeed)>.005){const nextHeading=driveHeading+driveSpeed/driveWheelbase*Math.tan(driveSteer)*dt,forwardX=Math.sin((driveHeading+nextHeading)/2),forwardZ=Math.cos((driveHeading+nextHeading)/2),nx=bus.position.x+forwardX*driveSpeed*dt,nz=bus.position.z+forwardZ*driveSpeed*dt,q=driveProject(nx,nz),fit=driveFootprintCheck(nx,nz,nextHeading);if(Math.abs(q.grade)>DRIVE_MAX_GRADE){driveSpeed=0;driveBlocked++;driveLastReason='勾配超過 · 安全停止'}else if(!fit.ok){driveSpeed=0;driveBlocked++;driveLastReason=fit.reason}else{driveHeading=nextHeading;driveDistanceAlong=q.station;bus.position.set(nx,q.y+.02,nz);bus.rotation.set(-Math.atan(q.grade),driveHeading,0);driveLastReason='';if(driveCoursePhase==='outbound'&&q.station>=driveCourse.lengthMetres-2.9){driveCoursePhase='return';driveSpeed=0;driveHud('チェックポイント到着 · ブレーキ後、S長押しで後退してください')}if(driveCoursePhase==='return'&&q.station<=3.1&&Math.abs(driveSpeed)<.1){driveCoursePhase='complete';driveSpeed=0;driveHud('GOAL · Aコース往復完了 · Rで再走行')}}}else if(driveLastReason)driveHud(driveLastReason+' · 安全停止');if(driveCoursePhase==='outbound'&&driveDistanceAlong>=driveCourse.lengthMetres-2.8)driveHud('チェックポイント · Sでブレーキ、停止後S長押しで後退');else if(driveCoursePhase==='return'&&driveDistanceAlong<=3.1&&Math.abs(driveSpeed)<.1){driveCoursePhase='complete';driveHud('GOAL · Aコース往復完了 · Rで再走行')}else if(!driveLastReason)driveHud(driveCoursePhase==='complete'?'GOAL · Aコース往復完了 · Rで再走行':`安全走行 · ${driveCoursePhase==='outbound'?'OUT':'RETURN'} · route ${driveDistanceAlong.toFixed(1)}m`)}

function render(data,nav,veg){phaseData=data;navData=nav;gapAreas=nav.blockedAreas||[];const t=data.terrain,v=t.vertices.flatMap(p=>p),b=data.bounds,nx=t.width,nz=t.height,dx=t.gridSpacingMetres[0],dz=t.gridSpacingMetres[1];groundY=(x,z)=>{const ix=Math.max(0,Math.min(nx-1,Math.round((x-b[0])/dx))),iz=Math.max(0,Math.min(nz-1,Math.round((z-b[1])/dz)));return t.vertices[iz*nx+ix][1]};const rootGeo=new THREE.BufferGeometry();rootGeo.setAttribute('position',new THREE.Float32BufferAttribute(v,3));rootGeo.setIndex(t.faces);rootGeo.computeVertexNormals();root.add(new THREE.Mesh(rootGeo,materials.terrain));addGroundcover(veg.vegetationAreas);addBaseRoads(data.roads);footprint(data.features.water,materials.water,.10);footprint(data.features.buildings,materials.building,.12,3.5);drawNav(nav);buildSpatialIndex(nav);testRoute=nav.testRoute;const p=testRoute?.points?.[0];if(p){makeRobot(veg.scenicSpawn?.position||p);if(veg.scenicSpawn?.heading!=null)robot.rotation.y=veg.scenicSpawn.heading}const w=b[2]-b[0],d=b[3]-b[1],cx=(b[0]+b[2])/2,cz=(b[1]+b[3])/2;controls.target.set(cx,2,cz);camera.position.set(cx+w*.396,2+d*.684,cz+d*.972);controls.update();loaded=true;setupVegetation(veg);setView('robot');restartGame();initDrive().catch(e=>{const q=$('#driveStatus');if(q)q.textContent='バス読込エラー · '+e.message});$('#vegetationStat').textContent=`OSM配置 ${veg.mappedTrees.length} · 航空写真推定 ${veg.estimatedTrees.filter(x=>x.source==='estimated_from_aerial_canopy').length} · 植生面推定 ${veg.estimatedTrees.filter(x=>x.source==='estimated_from_osm_vegetation_area').length} · 近景LOD 180m`;status.textContent=`地上園路 ${nav.runs.length} runs · OSM植生48件 · 欠損22区間未接続 · 橋面推定`;}

function addPhase2gDetails(surfaces){
 const under=[],ui=[],rp=[],ri=[],cp=[],ci=[];
 const quad=(p,ix,a,b,c,d)=>{const n=p.length/3;for(const v of [a,b,c,d])p.push(...v);ix.push(n,n+1,n+2,n+2,n+1,n+3)};
 const boxBeam=(p,ix,a,b,w,offset,height)=>{
  const dx=b[0]-a[0],dz=b[2]-a[2],len=Math.hypot(dx,dz)||1,nx=-dz/len*w/2,nz=dx/len*w/2;
  const lo0=a[1]+offset,lo1=b[1]+offset,hi0=lo0+height,hi1=lo1+height;
  const A=[a[0]+nx,lo0,a[2]+nz],B=[a[0]-nx,lo0,a[2]-nz],C=[b[0]+nx,lo1,b[2]+nz],D=[b[0]-nx,lo1,b[2]-nz],E=[A[0],hi0,A[2]],F=[B[0],hi0,B[2]],G=[C[0],hi1,C[2]],H=[D[0],hi1,D[2]];
  quad(p,ix,A,B,C,D);quad(p,ix,E,G,F,H);quad(p,ix,A,E,B,F);quad(p,ix,C,D,G,H);quad(p,ix,A,C,E,G);quad(p,ix,B,F,D,H)
 };
 const mapped=surfaces.filter(s=>s.kind==='mapped_osm_route');
 for(const s of mapped){
  const [l0,r0,l1,r1]=s.corners,drop=.32;
  const dl0=[l0[0],l0[1]-drop,l0[2]],dr0=[r0[0],r0[1]-drop,r0[2]],dl1=[l1[0],l1[1]-drop,l1[2]],dr1=[r1[0],r1[1]-drop,r1[2]];
  quad(under,ui,dl0,dr0,dl1,dr1);quad(under,ui,l0,l1,dl0,dl1);quad(under,ui,r0,dr0,r1,dr1);
  for(const [a,b] of [[l0,l1],[r0,r1]]){
   boxBeam(cp,ci,a,b,.18,0,.18);
   boxBeam(rp,ri,a,b,.10,.96,.09);
   const span=Math.hypot(b[0]-a[0],b[2]-a[2]),count=Math.max(1,Math.floor(span/2));
   for(let k=0;k<=count;k++){const t=k/count,p=[a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t,a[2]+(b[2]-a[2])*t];quad(rp,ri,[p[0]-.05,p[1],p[2]-.05],[p[0]+.05,p[1],p[2]-.05],[p[0]-.05,p[1]+.96,p[2]-.05],[p[0]+.05,p[1]+.96,p[2]-.05]);quad(rp,ri,[p[0]+.05,p[1],p[2]-.05],[p[0]+.05,p[1],p[2]+.05],[p[0]+.05,p[1]+.96,p[2]-.05],[p[0]+.05,p[1]+.96,p[2]+.05]);quad(rp,ri,[p[0]+.05,p[1],p[2]+.05],[p[0]-.05,p[1],p[2]+.05],[p[0]+.05,p[1]+.96,p[2]+.05],[p[0]-.05,p[1]+.96,p[2]+.05]);quad(rp,ri,[p[0]-.05,p[1],p[2]+.05],[p[0]-.05,p[1],p[2]-.05],[p[0]-.05,p[1]+.96,p[2]+.05],[p[0]-.05,p[1]+.96,p[2]-.05])}
  }
 }
 const make=(p,ix,mat,name)=>{if(!ix.length)return;const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(p,3));g.setIndex(ix);g.computeVertexNormals();const m=new THREE.Mesh(g,mat);m.name=name;m.userData={estimated:true,collisionEnabled:false,source:'Phase 2F mapped OSM way 33976871'};deckGroup.add(m)};
 make(under,ui,new THREE.MeshStandardMaterial({color:0x92999e,roughness:.9,side:THREE.DoubleSide}),'Phase 2I underside · 0.32m estimate · visual only');
 make(cp,ci,new THREE.MeshStandardMaterial({color:0xa6aaad,roughness:.82,side:THREE.DoubleSide}),'Phase 2I curbs · 0.18m estimate · visual only');
 make(rp,ri,new THREE.MeshStandardMaterial({color:0x626d70,roughness:.72,side:THREE.DoubleSide}),'Phase 2I guardrails · 1.05m estimate · visual only');
 return {mappedQuads:mapped.length,detailMeshes:deckGroup.children.length,collisionEnabled:false}
}

